    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); comp=[]; edge=False
        while q:
          y,x=q.popleft(); comp.append((y,x))
          if y in (0,h-1) or x in (0,w-1): edge=True
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
