              seen.add((yy,xx)); q.append((yy,xx))
        if not edge: enclosed.append(comp)
    # Fill enclosed pockets. Halo is zero immediately neighboring the outline,
    # excluding enclosed zeros themselves.
    inside={p for comp in enclosed for p in comp}
    halo=set()
